import re, numpy as np

def transform(grid):
    h,w=len(grid),len(grid[0])
    # separator rows
    for r,row in enumerate(grid):
        if len(set(row))==1 and r>0 and r<h-1:
            a=grid[:r]; b=grid[r+1:]
            if len(a)==len(b) and all(len(x)==w for x in a+b):
                return [[2 if a[i][j]!=0 and b[i][j]!=0 else 0 for j in range(w)] for i in range(len(a))]
    for c in range(w):
        vals={grid[r][c] for r in range(h)}
        if len(vals)==1 and c>0 and c<w-1 and c==w-c-1:
            a=[row[:c] for row in grid]; b=[row[c+1:] for row in grid]
            if all(len(x)==len(b[0]) for x in a+b):
                return [[2 if a[i][j]!=0 and b[i][j]!=0 else 0 for j in range(c)] for i in range(h)]
    raise ValueError('no split')

def parse_demo(text, n):
    # based on pair number and dimensions
    m=re.search(rf'Demo pair {n} input \((\d+)x(\d+)\):\n',text); h,w=map(int,m.groups()); start=m.end()
    lines=text[start:].splitlines()[:h]
    inp=[[int(x) for x in line.split()] for line in lines]
    marker=re.search(rf'Demo pair {n} output \((\d+)x(\d+)\):\n',text)
    oh,ow=map(int,marker.groups()); out=[[int(x) for x in line.split()] for line in text[marker.end():].splitlines()[:oh]]
    return inp,out
